SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
  if (!profile)
    return SessionStartupPref(SessionStartupPref::DEFAULT);

  SessionStartupPref pref = profile->GetSessionStartupPref();

  if (command_line.HasSwitch(switches::kRestoreLastSession))
    pref.type = SessionStartupPref::LAST;

  if (command_line.HasSwitch(switches::kNewTab))
    pref.type = SessionStartupPref::URLS;

  if (profile->IsGuestSession())
    pref.type = SessionStartupPref::DEFAULT;

  if (profile->IsOffTheRecord())
    pref.type = SessionStartupPref::DEFAULT;

  if (pref.type == SessionStartupPref::UNKNOWN)
    pref.type = SessionStartupPref::DEFAULT;

  return pref;
}

SessionStartupPref GetSessionStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref(SessionStartupPref::DEFAULT);

  if (!profile)
    return pref;

  // Handle first-time startup or browser restart scenarios.
  if (profile->IsNewProfile() || profile->IsGuestProfile()) {
    pref.type = SessionStartupPref::DEFAULT;
    pref.urls.clear();
    return pref;
  }

  // Chrome OS may have different session handling logic.
#if defined(OS_CHROMEOS)
  // Chrome OS specific logic here if needed.
#endif

  // Incognito mode does not restore the session.
  if (profile->IsIncognitoProfile()) {
    pref.type = SessionStartupPref::DEFAULT;
    pref.urls.clear();
    return pref;
  }

  // Apply default logic if no special cases are met.
  return pref;
}

