SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref(SessionStartupPref::DEFAULT);

  if (!profile)
    return pref;

  // Check if it's the first run or a restart.
  if (profile->IsNewProfile()) {
    pref.type = SessionStartupPref::LAST;
  } else if (profile->IsGuestProfile()) {
    pref.type = SessionStartupPref::LAST;
  } else {
    pref.type = SessionStartupPref::LAST;
    // Adjust based on command line args if needed.
    if (command_line.HasSwitch(switches::kNewTab))
      pref.type = SessionStartupPref::NEW_TAB;
    else if (command_line.HasSwitch(switches::kRestoreLastSession))
      pref.type = SessionStartupPref::LAST;
  }

  // Do not store session info for incognito.
  if (profile->IsOffTheRecord())
    pref.type = SessionStartupPref::DEFAULT;

  return pref;
}

SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
    SessionStartupPref pref(SessionStartupPref::DEFAULT);

    if (!profile)
        return pref;

    // Check if it's the first time user is starting Chrome.
    PrefService* pref_service = profile->GetPrefs();
    if (!pref_service->FindPreference(kSessionStartupPref))
        pref.type = SessionStartupPref::DEFAULT;

    // Adjust behavior for Chrome OS or other platforms.
    if (command_line.HasSwitch(switches::kGuestSession)) {
        pref.type = SessionStartupPref::LAST;
    }

    // Ensure incognito sessions do not store session info.
    if (profile->IsOffTheRecord()) {
        pref.type = SessionStartupPref::DEFAULT;
    }

    return pref;
}
